/**
 * P4-05 Japanese extraction evaluation dataset: types, loader and frozen
 * digest. All text is synthetic. The gold answers live in the committed
 * `dataset.v2.json`, generated by `generate.ts` before any model run, and are
 * pinned by DATASET_SHA256: changing a case, a gold answer or the split needs
 * a new dataset version and a new digest, never an in-place edit.
 *
 * v1 is retired (`retired/dataset.v1.retired.json`, kept only so a test can
 * show the independence check fails on it): 95 of its 100 holdout cases had the
 * same sentence skeleton as a dev case, so tuning on dev taught the holdout
 * templates. v2 draws the holdout from sentence structures dev never uses.
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import type { TypedValue } from "../../src/index.ts";

export const DATASET_VERSION = "ext-ja-v2";
/**
 * Evaluation version = dataset + thresholds + harness rules. ext-v2: dataset
 * ext-ja-v2 (holdout independent of dev) and ext-threshold-v2 (adopt recall is
 * gated). Results of ext-v1 are not comparable and are never mixed in.
 */
export const EVALUATION_VERSION = "ext-v2";
/** SHA-256 of the canonical (sorted-key) JSON of the committed dataset. */
export const DATASET_SHA256 =
	"100097a76c4832c2af76b419c0fc16153f412163a711399d12ad10e1fc0fd332";

export const groups = [
	"negation",
	"hypothesis",
	"hearsay",
	"other-person",
	"same-name",
	"period",
	"condition-mismatch",
	"multi-evidence",
	"correction",
	"ordinary",
] as const;
export type Group = (typeof groups)[number];

export const splits = ["dev", "holdout"] as const;
export type Split = (typeof splits)[number];

export const casesPerGroupPerSplit = 10;

export type ModelModality =
	| "asserted"
	| "reported"
	| "hypothetical"
	| "negated"
	| "question";
export type Classification = "negated" | "hypothetical" | "reported";
export type HoldReason =
	| "negated"
	| "hypothetical"
	| "question"
	| "unresolved_subject"
	| "ambiguous_subject"
	| "forgotten";
export type EntitySetName = "base" | "sameName";

export type SubjectQuery =
	| { readonly kind: "id"; readonly id: string }
	| { readonly kind: "alias"; readonly text: string };
export type CandidatePayload =
	| { readonly kind: "value"; readonly value: TypedValue }
	| {
			readonly kind: "relation";
			readonly relation: string;
			readonly object: { readonly kind: "id"; readonly id: string };
	  };

/** Offsets are Unicode code points into the utterance text, [start, end). */
export interface GoldQuote {
	readonly utteranceId: string;
	readonly startCp: number;
	readonly endCp: number;
}
export interface GoldValidTime {
	readonly precision: "exact" | "day" | "month" | "year";
	readonly original: string;
	readonly start?: { readonly earliest: number; readonly latest: number };
	readonly end?: { readonly earliest: number; readonly latest: number };
}
export type GoldCondition =
	| { readonly kind: "unspecified" }
	| { readonly kind: "expression"; readonly expression: unknown };

export interface GoldCandidate {
	readonly subject: SubjectQuery;
	readonly predicate: string;
	readonly payload: CandidatePayload;
	/** The primary supporting sentence. */
	readonly quote: GoldQuote;
	/** Other acceptable supporting sentences (multi-evidence). */
	readonly altQuotes?: readonly GoldQuote[];
	readonly validTime?: GoldValidTime;
	readonly condition: GoldCondition;
}
/** What a perfect model output contains for the case (used by fixtures). */
export interface ReferenceCandidate {
	readonly modality: ModelModality;
	readonly candidate: GoldCandidate;
}

export type Gold =
	| {
			readonly outcome: "adopt";
			/** asserted keeps the utterance origin; reported becomes a hypothesis. */
			readonly treatment: "asserted" | "reported";
			readonly classification?: "reported";
			readonly candidate: GoldCandidate;
			readonly reference: readonly ReferenceCandidate[];
	  }
	| {
			readonly outcome: "hold";
			readonly reason: HoldReason;
			readonly classification?: "negated" | "hypothetical";
			readonly reference: readonly ReferenceCandidate[];
	  };

export interface EvalUtterance {
	readonly utteranceId: string;
	readonly text: string;
	readonly origin: "user_report" | "document_claim";
}

export interface EvalCase {
	readonly caseId: string;
	readonly group: Group;
	readonly split: Split;
	readonly entitySet: EntitySetName;
	readonly utterances: readonly EvalUtterance[];
	/** Utterances the user asked to forget; citing them is a resurrection. */
	readonly forgotten?: {
		readonly utteranceIds: readonly string[];
		readonly claim: GoldCandidate;
	};
	readonly gold: Gold;
}

export interface DatasetEntity {
	readonly id: string;
	readonly revision: number;
	readonly displayName: string;
	readonly aliases: readonly string[];
	readonly externalRefs: readonly never[];
}
export interface Dataset {
	readonly version: string;
	readonly scope: { readonly principal: string; readonly scopeKey: string };
	readonly foreignScope: {
		readonly principal: string;
		readonly scopeKey: string;
	};
	/** The closed predicate vocabulary shown to the model. */
	readonly predicates: readonly string[];
	readonly entitySets: Readonly<
		Record<EntitySetName, readonly DatasetEntity[]>
	>;
	/** Entities of another Scope: never shown to the model. */
	readonly foreignEntities: readonly DatasetEntity[];
	readonly cases: readonly EvalCase[];
}

/** Stable key order, so the digest does not depend on object construction. */
export function stableStringify(value: unknown): string {
	if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
	if (typeof value === "object" && value !== null) {
		const object = value as Record<string, unknown>;
		const keys = Object.keys(object)
			.filter((key) => object[key] !== undefined)
			.sort();
		return `{${keys
			.map((key) => `${JSON.stringify(key)}:${stableStringify(object[key])}`)
			.join(",")}}`;
	}
	return JSON.stringify(value);
}

export const datasetDigest = (dataset: Dataset): string =>
	createHash("sha256").update(stableStringify(dataset)).digest("hex");

export class DatasetIntegrityError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "DatasetIntegrityError";
	}
}

/** Case ids of the foreign (other Scope) entities. */
export const foreignEntityIds = (dataset: Dataset): readonly string[] =>
	dataset.foreignEntities.map((entity) => entity.id);

/** Opaque, case-local source id for one utterance. */
export const sourceIdOf = (caseId: string, utteranceId: string): string =>
	`src-${caseId}-${utteranceId}`;

const encoder = new TextEncoder();

/** UTF-8 byte offset of a code point index. */
export function cpToByte(text: string, cp: number): number {
	let bytes = 0;
	let index = 0;
	for (const char of text) {
		if (index >= cp) break;
		bytes += encoder.encode(char).length;
		index += 1;
	}
	return bytes;
}

/** Code point index of a UTF-8 byte offset, or undefined mid-character. */
export function byteToCp(text: string, byte: number): number | undefined {
	let bytes = 0;
	let index = 0;
	for (const char of text) {
		if (bytes === byte) return index;
		if (bytes > byte) return undefined;
		bytes += encoder.encode(char).length;
		index += 1;
	}
	return bytes === byte ? index : undefined;
}

export const codePointLength = (text: string): number => [...text].length;

export const casesOf = (dataset: Dataset, split: Split): readonly EvalCase[] =>
	dataset.cases.filter((c) => c.split === split);

const datasetFile = new URL("./dataset.v2.json", import.meta.url);

/** Reads the committed dataset and refuses it when the digest differs. */
export function loadDataset(): Dataset {
	const dataset = JSON.parse(readFileSync(datasetFile, "utf8")) as Dataset;
	if (dataset.version !== DATASET_VERSION)
		throw new DatasetIntegrityError("dataset version mismatch");
	if (datasetDigest(dataset) !== DATASET_SHA256)
		throw new DatasetIntegrityError("dataset digest mismatch (gold changed)");
	return dataset;
}

/** Reads the committed file without the digest check (generator/test only). */
export function readCommittedDatasetUnchecked(): Dataset {
	return JSON.parse(readFileSync(datasetFile, "utf8")) as Dataset;
}
